import{H as e,gt as t,nt as n,rt as r}from"./chunks/framework.C8jghwzB.js";var i=JSON.parse(`{"title":"CLI reference","description":"Reference Let's Infer commands for setup, model installation, topology, keys, status, updates, benchmarks, recovery, and uninstall.","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://letsinfer.ai/docs/reference/cli.html"}],["link",{"rel":"alternate","type":"text/plain","href":"/llms.txt","title":"Let's Infer for language models"}],["link",{"rel":"license","href":"https://github.com/letsinferlabs/letsinfer/blob/main/LICENSE"}],["meta",{"name":"author","content":"Let's Infer"}],["meta",{"name":"robots","content":"index, follow, max-image-preview:large, max-snippet:-1, max-video-preview:-1"}],["meta",{"property":"og:site_name","content":"Let's Infer"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"CLI reference · Let's Infer"}],["meta",{"property":"og:description","content":"Reference Let's Infer commands for setup, model installation, topology, keys, status, updates, benchmarks, recovery, and uninstall."}],["meta",{"property":"og:url","content":"https://letsinfer.ai/docs/reference/cli.html"}],["meta",{"property":"og:image","content":"https://letsinfer.ai/og-image.png"}],["meta",{"property":"og:image:type","content":"image/png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:image:alt","content":"Let's Infer — local AI, installed like software"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"CLI reference · Let's Infer"}],["meta",{"name":"twitter:description","content":"Reference Let's Infer commands for setup, model installation, topology, keys, status, updates, benchmarks, recovery, and uninstall."}],["meta",{"name":"twitter:image","content":"https://letsinfer.ai/og-image.png"}],["meta",{"name":"twitter:image:alt","content":"Let's Infer — local AI, installed like software"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"Organization\\",\\"@id\\":\\"https://letsinfer.ai/#organization\\",\\"name\\":\\"Let's Infer\\",\\"url\\":\\"https://letsinfer.ai/\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://letsinfer.ai/logo.png\\",\\"contentUrl\\":\\"https://letsinfer.ai/logo.png\\",\\"width\\":512,\\"height\\":512},\\"sameAs\\":[\\"https://github.com/letsinferlabs\\"]},{\\"@type\\":\\"WebSite\\",\\"@id\\":\\"https://letsinfer.ai/#website\\",\\"name\\":\\"Let's Infer\\",\\"url\\":\\"https://letsinfer.ai/\\",\\"description\\":\\"Turn your AI hardware into one reliable inference service.\\",\\"inLanguage\\":\\"en-US\\",\\"publisher\\":{\\"@id\\":\\"https://letsinfer.ai/#organization\\"}},{\\"@type\\":[\\"SoftwareApplication\\",\\"SoftwareSourceCode\\"],\\"@id\\":\\"https://letsinfer.ai/#software\\",\\"name\\":\\"Let's Infer\\",\\"alternateName\\":\\"letsinfer\\",\\"description\\":\\"Open-source, engine-agnostic inference distribution and runtime manager for local AI hardware.\\",\\"url\\":\\"https://letsinfer.ai/\\",\\"codeRepository\\":\\"https://github.com/letsinferlabs/letsinfer\\",\\"downloadUrl\\":\\"https://letsinfer.ai/install.sh\\",\\"license\\":\\"https://github.com/letsinferlabs/letsinfer/blob/main/LICENSE\\",\\"applicationCategory\\":\\"DeveloperApplication\\",\\"operatingSystem\\":\\"Linux, macOS\\",\\"isAccessibleForFree\\":true,\\"publisher\\":{\\"@id\\":\\"https://letsinfer.ai/#organization\\"}},{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://letsinfer.ai/docs/reference/cli.html#article\\",\\"headline\\":\\"CLI reference\\",\\"description\\":\\"Reference Let's Infer commands for setup, model installation, topology, keys, status, updates, benchmarks, recovery, and uninstall.\\",\\"url\\":\\"https://letsinfer.ai/docs/reference/cli.html\\",\\"mainEntityOfPage\\":\\"https://letsinfer.ai/docs/reference/cli.html\\",\\"inLanguage\\":\\"en-US\\",\\"isPartOf\\":{\\"@id\\":\\"https://letsinfer.ai/#website\\"},\\"about\\":{\\"@id\\":\\"https://letsinfer.ai/#software\\"},\\"author\\":{\\"@id\\":\\"https://letsinfer.ai/#organization\\"},\\"publisher\\":{\\"@id\\":\\"https://letsinfer.ai/#organization\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://letsinfer.ai/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Documentation\\",\\"item\\":\\"https://letsinfer.ai/docs/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"CLI reference\\",\\"item\\":\\"https://letsinfer.ai/docs/reference/cli.html\\"}]}]}"]]},"headers":[],"relativePath":"docs/reference/cli.md","filePath":"docs/reference/cli.md"}`),a={name:`docs/reference/cli.md`};function o(e,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[r(`<h1 id="cli-reference" tabindex="-1">CLI reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to “CLI reference”">​</a></h1><p><a href="./../">Back to documentation</a></p><p>The installer initializes the node automatically. Run <code>letsinfer COMMAND --help</code> for exact options in the installed release; retired pre-launch command paths have no aliases.</p><h2 id="complete-command-tree" tabindex="-1">Complete command tree <a class="header-anchor" href="#complete-command-tree" aria-label="Permalink to “Complete command tree”">​</a></h2><p>The following tree is the complete public command surface. Each command has one responsibility and a two-sentence explanation directly beneath it.</p><h3 id="letsinfer-status" tabindex="-1"><code>letsinfer status</code> <a class="header-anchor" href="#letsinfer-status" aria-label="Permalink to “letsinfer status”">​</a></h3><p>Shows the complete node, service, hardware, model, engine-group, protection, and telemetry state. Physically shared memory is shown as unified memory, while discrete hosts report GPU VRAM and installed system RAM separately; use <code>--json</code> when another program needs the result.</p><h3 id="letsinfer-topology" tabindex="-1"><code>letsinfer topology</code> <a class="header-anchor" href="#letsinfer-topology" aria-label="Permalink to “letsinfer topology”">​</a></h3><p>Shows the authenticated main-and-child graph with verified links, node health, model placements, and current host network traffic. Its live terminal view animates one continuous main-to-child trunk independently of one-second state polling, flows through every child before repeating, reports standalone and engine-group placements, and pauses only groups that depend on a lost verified link, while <code>--json</code> returns one exact snapshot.</p><h3 id="letsinfer-doctor" tabindex="-1"><code>letsinfer doctor</code> <a class="header-anchor" href="#letsinfer-doctor" aria-label="Permalink to “letsinfer doctor”">​</a></h3><p>Audits operational and publication readiness without changing state. Its checks explain what is healthy, degraded, or blocking and support <code>--json</code>.</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>letsinfer node</span></span>
<span class="line"><span>├── info [NODE]</span></span>
<span class="line"><span>├── list</span></span>
<span class="line"><span>├── usage</span></span>
<span class="line"><span>├── add</span></span>
<span class="line"><span>├── pause [NODE]</span></span>
<span class="line"><span>├── resume [NODE]</span></span>
<span class="line"><span>└── remove [NODE]</span></span></code></pre></div><h3 id="letsinfer-node-info-node" tabindex="-1"><code>letsinfer node info [NODE]</code> <a class="header-anchor" href="#letsinfer-node-info-node" aria-label="Permalink to “letsinfer node info [NODE]”">​</a></h3><p>Shows a selected node&#39;s identity, role, online state, hardware, compatible targets, and observed links. Omit <code>NODE</code> for the role-aware selector, or use <code>--json</code> without a target to retain local-node automation.</p><h3 id="letsinfer-node-list" tabindex="-1"><code>letsinfer node list</code> <a class="header-anchor" href="#letsinfer-node-list" aria-label="Permalink to “letsinfer node list”">​</a></h3><p>Lists the main and every child with role, availability, placement, and health state. Use <code>--json</code> to consume the topology without parsing the human table.</p><h3 id="letsinfer-node-usage" tabindex="-1"><code>letsinfer node usage</code> <a class="header-anchor" href="#letsinfer-node-usage" aria-label="Permalink to “letsinfer node usage”">​</a></h3><p>Shows local Let’s Infer storage by category, filesystem free space, and the exact inactive data that can be reclaimed. Use <code>--clean</code> to remove reviewed completed benchmarks, inactive model data, and rebuildable caches; <code>--category</code> limits the plan, <code>--yes</code> enables non-interactive cleanup, and removed model data is downloaded and verified again before any affected runtime starts.</p><h3 id="letsinfer-node-add" tabindex="-1"><code>letsinfer node add</code> <a class="header-anchor" href="#letsinfer-node-add" aria-label="Permalink to “letsinfer node add”">​</a></h3><p>Shows incoming requests and discovers certificate-identified nodes that can be adopted as children. The main selects the pinned node and the candidate accepts that exact request locally, which activates the child without a second code; provider-owned high-speed networking is prepared without overwriting an external plan, while child invocation confirms coordinated detach and returns the machine to standalone discovery.</p><h3 id="letsinfer-node-pause-node" tabindex="-1"><code>letsinfer node pause [NODE]</code> <a class="header-anchor" href="#letsinfer-node-pause-node" aria-label="Permalink to “letsinfer node pause [NODE]”">​</a></h3><p>Stops assigning new work to the selected node while retaining membership and placement records. Omit <code>NODE</code> for the selector; a child can pause itself through the main, and self/main targets require interactive confirmation.</p><h3 id="letsinfer-node-resume-node" tabindex="-1"><code>letsinfer node resume [NODE]</code> <a class="header-anchor" href="#letsinfer-node-resume-node" aria-label="Permalink to “letsinfer node resume [NODE]”">​</a></h3><p>Restores new-work admission to a paused selected node without recreating membership or model state. A child can resume itself through the main, and an explicit node keeps automation deterministic.</p><h3 id="letsinfer-node-remove-node" tabindex="-1"><code>letsinfer node remove [NODE]</code> <a class="header-anchor" href="#letsinfer-node-remove-node" aria-label="Permalink to “letsinfer node remove [NODE]”">​</a></h3><p>On a main, removes a selected child after confirmation and refuses while a live placement depends on it. On a child, removes itself through authenticated coordinated detach and becomes a standalone addable main.</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>letsinfer model</span></span>
<span class="line"><span>├── list [MODEL]</span></span>
<span class="line"><span>├── install [MODEL]</span></span>
<span class="line"><span>├── remove MODEL</span></span>
<span class="line"><span>├── pause MODEL</span></span>
<span class="line"><span>├── resume MODEL</span></span>
<span class="line"><span>├── restart MODEL</span></span>
<span class="line"><span>├── recover MODEL</span></span>
<span class="line"><span>├── rollback MODEL</span></span>
<span class="line"><span>└── logs MODEL</span></span></code></pre></div><h3 id="letsinfer-model-list-model" tabindex="-1"><code>letsinfer model list [MODEL]</code> <a class="header-anchor" href="#letsinfer-model-list-model" aria-label="Permalink to “letsinfer model list [MODEL]”">​</a></h3><p>Shows the signed catalog and installed models in one view, with installed and recommended versions clearly marked. Filters expose installed entries, exact versions, compatible targets, refreshed catalog state, and JSON output.</p><h3 id="letsinfer-model-install-model" tabindex="-1"><code>letsinfer model install [MODEL]</code> <a class="header-anchor" href="#letsinfer-model-install-model" aria-label="Permalink to “letsinfer model install [MODEL]”">​</a></h3><p>Installs a named model through the signed catalog and target matcher, accepts an explicit local runtime directory, archive, or digest-pinned runtime OCI, or opens the node/model selector when <code>MODEL</code> is omitted. Assigning the same model to multiple compatible nodes creates replicas automatically, while an exact operator-selected source remains unqualified but receives the ordinary managed group and route; use <code>--node</code> to bind a compatible node, and use OCI when a content-addressed local object is not already present on a remote child.</p><h3 id="letsinfer-model-remove-model" tabindex="-1"><code>letsinfer model remove MODEL</code> <a class="header-anchor" href="#letsinfer-model-remove-model" aria-label="Permalink to “letsinfer model remove MODEL”">​</a></h3><p>Removes the selected model from one node or, with explicit confirmation, from all nodes that host it. Safety checks prevent ambiguous or dependency-breaking removal.</p><h3 id="letsinfer-model-pause-model" tabindex="-1"><code>letsinfer model pause MODEL</code> <a class="header-anchor" href="#letsinfer-model-pause-model" aria-label="Permalink to “letsinfer model pause MODEL”">​</a></h3><p>Stops admitting new inference work for the selected logical model without deleting its immutable runtime or placement. The paused model remains visible in status and can be resumed later.</p><h3 id="letsinfer-model-resume-model" tabindex="-1"><code>letsinfer model resume MODEL</code> <a class="header-anchor" href="#letsinfer-model-resume-model" aria-label="Permalink to “letsinfer model resume MODEL”">​</a></h3><p>Returns a paused logical model to service after its existing safety checks pass. Resume does not clear a protection trip or replace recovery.</p><h3 id="letsinfer-model-restart-model" tabindex="-1"><code>letsinfer model restart MODEL</code> <a class="header-anchor" href="#letsinfer-model-restart-model" aria-label="Permalink to “letsinfer model restart MODEL”">​</a></h3><p>Restarts the selected model&#39;s engine groups while preserving its chosen runtime and safety history. Use it for ordinary lifecycle recovery, not as an acknowledgement of a Watchdog protection event.</p><h3 id="letsinfer-model-recover-model" tabindex="-1"><code>letsinfer model recover MODEL</code> <a class="header-anchor" href="#letsinfer-model-recover-model" aria-label="Permalink to “letsinfer model recover MODEL”">​</a></h3><p>Explicitly acknowledges a protection trip and attempts recovery after its cause has been corrected. This is the only lifecycle command permitted to clear that protected state.</p><h3 id="letsinfer-model-rollback-model" tabindex="-1"><code>letsinfer model rollback MODEL</code> <a class="header-anchor" href="#letsinfer-model-rollback-model" aria-label="Permalink to “letsinfer model rollback MODEL”">​</a></h3><p>Plans or applies a rollback to the retained prior immutable runtime for the selected model. Use <code>--dry-run</code> to review the exact groups and version change before mutation.</p><h3 id="letsinfer-model-logs-model" tabindex="-1"><code>letsinfer model logs MODEL</code> <a class="header-anchor" href="#letsinfer-model-logs-model" aria-label="Permalink to “letsinfer model logs MODEL”">​</a></h3><p>Streams or tails logs for the selected model&#39;s local engine group. Specify a group only when more than one local group makes the model selection ambiguous.</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>letsinfer benchmark</span></span>
<span class="line"><span>├── run MODEL</span></span>
<span class="line"><span>├── list MODEL</span></span>
<span class="line"><span>├── status</span></span>
<span class="line"><span>├── stop</span></span>
<span class="line"><span>├── clean</span></span>
<span class="line"><span>└── verification</span></span>
<span class="line"><span>    ├── run PULL_REQUEST_URL</span></span>
<span class="line"><span>    ├── status</span></span>
<span class="line"><span>    └── stop</span></span></code></pre></div><h3 id="letsinfer-benchmark-run-model" tabindex="-1"><code>letsinfer benchmark run MODEL</code> <a class="header-anchor" href="#letsinfer-benchmark-run-model" aria-label="Permalink to “letsinfer benchmark run MODEL”">​</a></h3><p>Starts or resumes the canonical benchmark matrix for an installed model and the requested workload options. The job is durable, so Ctrl-C detaches while <code>benchmark stop</code> performs cancellation.</p><h3 id="letsinfer-benchmark-list-model" tabindex="-1"><code>letsinfer benchmark list MODEL</code> <a class="header-anchor" href="#letsinfer-benchmark-list-model" aria-label="Permalink to “letsinfer benchmark list MODEL”">​</a></h3><p>Lists the benchmark cells that would run for the selected model and workload options. It is a read-only way to inspect the matrix before consuming runtime capacity.</p><h3 id="letsinfer-benchmark-status" tabindex="-1"><code>letsinfer benchmark status</code> <a class="header-anchor" href="#letsinfer-benchmark-status" aria-label="Permalink to “letsinfer benchmark status”">​</a></h3><p>Shows the active or most recent benchmark job, progress, workload, and durable result state. Use <code>--json</code> for monitoring and CI integrations.</p><h3 id="letsinfer-benchmark-stop" tabindex="-1"><code>letsinfer benchmark stop</code> <a class="header-anchor" href="#letsinfer-benchmark-stop" aria-label="Permalink to “letsinfer benchmark stop”">​</a></h3><p>Requests durable cancellation of the active ordinary benchmark and waits for its restoration boundary. It is distinct from Ctrl-C, which only detaches the terminal.</p><h3 id="letsinfer-benchmark-clean" tabindex="-1"><code>letsinfer benchmark clean</code> <a class="header-anchor" href="#letsinfer-benchmark-clean" aria-label="Permalink to “letsinfer benchmark clean”">​</a></h3><p>Removes completed local benchmark working data after explicit confirmation. It does not delete installed models or reinterpret failed evidence as a pass.</p><h3 id="letsinfer-benchmark-verification-run-pull-request-url" tabindex="-1"><code>letsinfer benchmark verification run PULL_REQUEST_URL</code> <a class="header-anchor" href="#letsinfer-benchmark-verification-run-pull-request-url" aria-label="Permalink to “letsinfer benchmark verification run PULL_REQUEST_URL”">​</a></h3><p>Runs the public verification contract against the exact finalized artifact for an eligible runtimes pull request. It never executes pull-request source or promotes an author&#39;s local result into qualification.</p><h3 id="letsinfer-benchmark-verification-status" tabindex="-1"><code>letsinfer benchmark verification status</code> <a class="header-anchor" href="#letsinfer-benchmark-verification-status" aria-label="Permalink to “letsinfer benchmark verification status”">​</a></h3><p>Shows progress and outcome for the active or most recent pull-request verification job. Its JSON form is suitable for durable monitoring.</p><h3 id="letsinfer-benchmark-verification-stop" tabindex="-1"><code>letsinfer benchmark verification stop</code> <a class="header-anchor" href="#letsinfer-benchmark-verification-stop" aria-label="Permalink to “letsinfer benchmark verification stop”">​</a></h3><p>Requests durable cancellation of the active verification job and restores the prior serving state. It does not edit the pull request or publish evidence.</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>letsinfer auth</span></span>
<span class="line"><span>├── controller</span></span>
<span class="line"><span>│   ├── add</span></span>
<span class="line"><span>│   ├── list</span></span>
<span class="line"><span>│   └── revoke CONTROLLER</span></span>
<span class="line"><span>└── key</span></span>
<span class="line"><span>    ├── create NAME</span></span>
<span class="line"><span>    ├── list</span></span>
<span class="line"><span>    ├── show KEY</span></span>
<span class="line"><span>    ├── rotate KEY</span></span>
<span class="line"><span>    ├── revoke KEY</span></span>
<span class="line"><span>    └── update KEY</span></span></code></pre></div><h3 id="letsinfer-auth-controller-add" tabindex="-1"><code>letsinfer auth controller add</code> <a class="header-anchor" href="#letsinfer-auth-controller-add" aria-label="Permalink to “letsinfer auth controller add”">​</a></h3><p>Opens the transient TLS pairing listener and displays the human comparison code for one controller. Ctrl-C closes the listener and reports <code>Pairing cancelled</code> without persisting an unfinished enrollment.</p><h3 id="letsinfer-auth-controller-list" tabindex="-1"><code>letsinfer auth controller list</code> <a class="header-anchor" href="#letsinfer-auth-controller-list" aria-label="Permalink to “letsinfer auth controller list”">​</a></h3><p>Lists enrolled controllers and their non-secret identity and policy state. This sensitive read is audited and supports machine-readable output.</p><h3 id="letsinfer-auth-controller-revoke-controller" tabindex="-1"><code>letsinfer auth controller revoke CONTROLLER</code> <a class="header-anchor" href="#letsinfer-auth-controller-revoke-controller" aria-label="Permalink to “letsinfer auth controller revoke CONTROLLER”">​</a></h3><p>Revokes the selected controller&#39;s authority to manage the main. The operation is audited and does not affect unrelated inference API keys.</p><h3 id="letsinfer-auth-key-create-name" tabindex="-1"><code>letsinfer auth key create NAME</code> <a class="header-anchor" href="#letsinfer-auth-key-create-name" aria-label="Permalink to “letsinfer auth key create NAME”">​</a></h3><p>Creates an inference API key and optional policy for the named application. The plaintext secret is shown exactly once and is never written to the audit chain.</p><h3 id="letsinfer-auth-key-list" tabindex="-1"><code>letsinfer auth key list</code> <a class="header-anchor" href="#letsinfer-auth-key-list" aria-label="Permalink to “letsinfer auth key list”">​</a></h3><p>Lists API-key identities, policy summaries, and lifecycle state without revealing plaintext secrets. This sensitive read is audited and supports JSON.</p><h3 id="letsinfer-auth-key-show-key" tabindex="-1"><code>letsinfer auth key show KEY</code> <a class="header-anchor" href="#letsinfer-auth-key-show-key" aria-label="Permalink to “letsinfer auth key show KEY”">​</a></h3><p>Shows one key&#39;s metadata and effective policy without recovering its original secret. Use the key identifier or unambiguous name reported by <code>auth key list</code>.</p><h3 id="letsinfer-auth-key-rotate-key" tabindex="-1"><code>letsinfer auth key rotate KEY</code> <a class="header-anchor" href="#letsinfer-auth-key-rotate-key" aria-label="Permalink to “letsinfer auth key rotate KEY”">​</a></h3><p>Replaces a key&#39;s secret while preserving its application identity and current policy. The replacement secret is displayed once and the prior secret becomes invalid.</p><h3 id="letsinfer-auth-key-revoke-key" tabindex="-1"><code>letsinfer auth key revoke KEY</code> <a class="header-anchor" href="#letsinfer-auth-key-revoke-key" aria-label="Permalink to “letsinfer auth key revoke KEY”">​</a></h3><p>Permanently disables the selected inference API key. The audited revocation does not expose the key&#39;s plaintext value.</p><h3 id="letsinfer-auth-key-update-key" tabindex="-1"><code>letsinfer auth key update KEY</code> <a class="header-anchor" href="#letsinfer-auth-key-update-key" aria-label="Permalink to “letsinfer auth key update KEY”">​</a></h3><p>Updates the selected key&#39;s model scope, expiry, rate, concurrency, context, tenant, or application policy. Unspecified policy fields retain their current values rather than being silently reset.</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>letsinfer exposure</span></span>
<span class="line"><span>├── status</span></span>
<span class="line"><span>├── enable</span></span>
<span class="line"><span>└── disable</span></span></code></pre></div><h3 id="letsinfer-exposure-status" tabindex="-1"><code>letsinfer exposure status</code> <a class="header-anchor" href="#letsinfer-exposure-status" aria-label="Permalink to “letsinfer exposure status”">​</a></h3><p>Shows whether the authenticated inference gateway is exposed beyond its local network boundary and reports the effective endpoint state. The command is read-only and supports JSON.</p><h3 id="letsinfer-exposure-enable" tabindex="-1"><code>letsinfer exposure enable</code> <a class="header-anchor" href="#letsinfer-exposure-enable" aria-label="Permalink to “letsinfer exposure enable”">​</a></h3><p>Enables the configured public exposure path for the authenticated inference gateway after readiness checks pass. It does not make node-control or pairing interfaces public.</p><h3 id="letsinfer-exposure-disable" tabindex="-1"><code>letsinfer exposure disable</code> <a class="header-anchor" href="#letsinfer-exposure-disable" aria-label="Permalink to “letsinfer exposure disable”">​</a></h3><p>Disables the configured public inference exposure while leaving local serving and model placement intact. The audited change does not revoke existing API keys.</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>letsinfer audit</span></span>
<span class="line"><span>├── list</span></span>
<span class="line"><span>├── show EVENT</span></span>
<span class="line"><span>├── verify</span></span>
<span class="line"><span>└── export --output FILE</span></span></code></pre></div><h3 id="letsinfer-audit-list" tabindex="-1"><code>letsinfer audit list</code> <a class="header-anchor" href="#letsinfer-audit-list" aria-label="Permalink to “letsinfer audit list”">​</a></h3><p>Lists audit events in chain order with their non-secret summaries. Filters and JSON output support bounded operational review.</p><h3 id="letsinfer-audit-show-event" tabindex="-1"><code>letsinfer audit show EVENT</code> <a class="header-anchor" href="#letsinfer-audit-show-event" aria-label="Permalink to “letsinfer audit show EVENT”">​</a></h3><p>Shows the complete recorded fields for one audit event without exposing plaintext credentials, prompts, or responses. The event identifier comes from <code>audit list</code>.</p><h3 id="letsinfer-audit-verify" tabindex="-1"><code>letsinfer audit verify</code> <a class="header-anchor" href="#letsinfer-audit-verify" aria-label="Permalink to “letsinfer audit verify”">​</a></h3><p>Verifies the append-only audit chain and reports the first integrity failure if one exists. It performs no repair or mutation.</p><h3 id="letsinfer-audit-export-output-file" tabindex="-1"><code>letsinfer audit export --output FILE</code> <a class="header-anchor" href="#letsinfer-audit-export-output-file" aria-label="Permalink to “letsinfer audit export --output FILE”">​</a></h3><p>Writes the bounded audit export to the explicitly selected file. Exported records preserve chain evidence while excluding prompts, responses, and plaintext credentials.</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>letsinfer update</span></span>
<span class="line"><span>├── check</span></span>
<span class="line"><span>├── core [VERSION]</span></span>
<span class="line"><span>└── model [MODEL]</span></span></code></pre></div><h3 id="letsinfer-update-check" tabindex="-1"><code>letsinfer update check</code> <a class="header-anchor" href="#letsinfer-update-check" aria-label="Permalink to “letsinfer update check”">​</a></h3><p>Checks Core and installed-model update availability without applying changes. It works before full node initialization and supports JSON.</p><h3 id="letsinfer-update-core-version" tabindex="-1"><code>letsinfer update core [VERSION]</code> <a class="header-anchor" href="#letsinfer-update-core-version" aria-label="Permalink to “letsinfer update core [VERSION]”">​</a></h3><p>Stages, verifies, and activates the recommended Core release or the explicitly selected version. Core updates do not silently change installed model runtimes.</p><h3 id="letsinfer-update-model-model" tabindex="-1"><code>letsinfer update model [MODEL]</code> <a class="header-anchor" href="#letsinfer-update-model-model" aria-label="Permalink to “letsinfer update model [MODEL]”">​</a></h3><p>Plans or applies a qualified runtime update for one installed model, or opens the installed-model selector when <code>MODEL</code> is omitted. Use <code>--dry-run</code> to inspect every affected engine group before activation.</p><h3 id="letsinfer-uninstall" tabindex="-1"><code>letsinfer uninstall</code> <a class="header-anchor" href="#letsinfer-uninstall" aria-label="Permalink to “letsinfer uninstall”">​</a></h3><p>Removes Let’s Infer-owned services, containers, images, and data after explicit confirmation. Use <code>--keep-models</code> to preserve model storage within the stated uninstall boundary.</p><h2 id="machine-readable-output" tabindex="-1">Machine-readable output <a class="header-anchor" href="#machine-readable-output" aria-label="Permalink to “Machine-readable output”">​</a></h2><p>Use <code>--json</code> where declared for automation. Human presentation may evolve, while JSON documents, raw log streams, exported artifacts, and exit status are the durable contracts.</p><p>Runtime development and deterministic pack authoring are intentionally absent from the product CLI. Those workflows live in the public <code>letsinfer-runtime-authoring</code> skill.</p>`,109)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};